s:0:\"\";}}}}}}}}}}}}}}}}s:4:\"type\";i:128;s:7:\"headers\";a:10:{s:6:\"server\";s:5:\"nginx\";s:4:\"date\";s:29:\"Thu, 19 Nov 2026 22:13:35 GMT\";s:12:\"content-type\";s:8:\"text/xml\";s:13:\"last-modified\";s:29:\"Thu, 19 Nov 2026 22:00:30 GMT\";s:4:\"vary\";s:15:\"Accept-Encoding\";s:15:\"x-frame-options\";s:10:\"SAMEORIGIN\";s:16:\"content-encoding\";s:4:\"gzip\";s:7:\"alt-svc\";s:5:\"clear\";s:13:\"x-remembering\";s:58:\"Eric Binnion <https://friendsofericbinnion.wordpress.com/>\";s:4:\"x-nc\";s:9:\"HIT dca 1\";}s:5:\"build\";i:1795124945;s:21:\"cache_expiration_time\";i:1795169616;s:23:\"__cache_expiration_time\";i:1795169616;}', 'off');
